export type PaymentMethod = "cash" | "transfer";

export interface Category {
  id: string;
  name: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  categoryId: string;
  description: string;
  imageUrl: string;
}

export interface TransactionItem {
  productId: string;
  name: string;
  price: number;
  qty: number;
}

export interface Transaction {
  id: string;
  createdAt: string;
  items: TransactionItem[];
  total: number;
  payment: PaymentMethod;
}

export interface AppState {
  categories: Category[];
  products: Product[];
  transactions: Transaction[];
}

const idr = new Intl.NumberFormat("id-ID", {
  style: "currency",
  currency: "IDR",
  maximumFractionDigits: 0,
});

export function formatIdr(n: number): string {
  return idr.format(n);
}

export function formatDate(iso: string): string {
  return new Date(iso).toLocaleString("id-ID", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function formatDateShort(iso: string): string {
  return new Date(iso).toLocaleDateString("id-ID", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export function startOfDay(d: Date): Date {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

export function startOfWeekMonday(d: Date): Date {
  const x = startOfDay(d);
  const day = x.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  x.setDate(x.getDate() + diff);
  return x;
}

export function startOfMonth(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), 1);
}

export function orderIdDisplay(id: string): string {
  return id.slice(0, 8).toUpperCase();
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { AppState, Category, PaymentMethod, Product, Transaction } from "../types";

const STORAGE_KEY = "pempek_novi_store_v1";

function uid(): string {
  return crypto.randomUUID();
}

const img = (seed: number) =>
  `https://images.unsplash.com/photo-${1546069901 + seed}?w=400&h=300&fit=crop&q=80`;

function buildInitialState(): AppState {
  const catPempek: Category = { id: "c1", name: "Pempek" };
  const catMinuman: Category = { id: "c2", name: "Minuman" };
  const categories: Category[] = [catPempek, catMinuman];

  const products: Product[] = [
    {
      id: "p1",
      name: "Pempek Kapal Selam",
      price: 18000,
      stock: 40,
      categoryId: "c1",
      description: "Telur di dalam adonan ikan, khas Palembang.",
      imageUrl: img(1),
    },
    {
      id: "p2",
      name: "Pempek Lenjer",
      price: 12000,
      stock: 55,
      categoryId: "c1",
      description: "Bentuk panjang, tekstur kenyal.",
      imageUrl: img(2),
    },
    {
      id: "p3",
      name: "Pempek Adaan",
      price: 15000,
      stock: 48,
      categoryId: "c1",
      description: "Bulat dengan ebi di tengah.",
      imageUrl: img(3),
    },
    {
      id: "p4",
      name: "Tekwan",
      price: 14000,
      stock: 35,
      categoryId: "c1",
      description: "Sup bening dengan suiran ikan.",
      imageUrl: img(4),
    },
    {
      id: "p5",
      name: "Es Jeruk",
      price: 8000,
      stock: 100,
      categoryId: "c2",
      description: "Segar, peras jeruk lokal.",
      imageUrl: img(5),
    },
    {
      id: "p6",
      name: "Teh Manis",
      price: 5000,
      stock: 120,
      categoryId: "c2",
      description: "Teh tubruk dingin.",
      imageUrl: img(6),
    },
  ];

  const now = new Date();
  const mkTx = (
    daysAgo: number,
    items: { productId: string; name: string; price: number; qty: number }[],
    payment: PaymentMethod,
  ): Transaction => {
    const d = new Date(now);
    d.setDate(d.getDate() - daysAgo);
    d.setHours(10 + (daysAgo % 5), 30, 0, 0);
    const total = items.reduce((s, i) => s + i.price * i.qty, 0);
    return {
      id: uid(),
      createdAt: d.toISOString(),
      items: items.map((i) => ({
        productId: i.productId,
        name: i.name,
        price: i.price,
        qty: i.qty,
      })),
      total,
      payment,
    };
  };

  const transactions: Transaction[] = [
    mkTx(0, [{ productId: "p1", name: "Pempek Kapal Selam", price: 18000, qty: 2 }], "cash"),
    mkTx(0, [{ productId: "p3", name: "Pempek Adaan", price: 15000, qty: 3 }], "transfer"),
    mkTx(1, [{ productId: "p2", name: "Pempek Lenjer", price: 12000, qty: 4 }], "cash"),
    mkTx(2, [{ productId: "p4", name: "Tekwan", price: 14000, qty: 2 }], "transfer"),
    mkTx(5, [{ productId: "p1", name: "Pempek Kapal Selam", price: 18000, qty: 1 }], "cash"),
    mkTx(8, [{ productId: "p5", name: "Es Jeruk", price: 8000, qty: 3 }], "cash"),
    mkTx(12, [{ productId: "p2", name: "Pempek Lenjer", price: 12000, qty: 6 }], "transfer"),
    mkTx(20, [{ productId: "p3", name: "Pempek Adaan", price: 15000, qty: 2 }], "cash"),
    mkTx(35, [{ productId: "p1", name: "Pempek Kapal Selam", price: 18000, qty: 5 }], "transfer"),
    mkTx(50, [{ productId: "p4", name: "Tekwan", price: 14000, qty: 3 }], "cash"),
  ];

  return { categories, products, transactions };
}

function loadState(): AppState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as AppState;
      if (parsed?.products?.length) return parsed;
    }
  } catch {
    /* ignore */
  }
  return buildInitialState();
}

function persist(state: AppState) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

type StoreContextValue = {
  state: AppState;
  categories: Category[];
  products: Product[];
  transactions: Transaction[];
  getProduct: (id: string) => Product | undefined;
  getCategoryName: (id: string) => string;
  addProduct: (p: Omit<Product, "id">) => void;
  updateProduct: (id: string, p: Omit<Product, "id">) => void;
  deleteProduct: (id: string) => void;
  addCategory: (name: string) => void;
  checkout: (cart: Map<string, number>, payment: PaymentMethod) => Transaction | null;
  resetDemoData: () => void;
};

const StoreContext = createContext<StoreContextValue | null>(null);

export function StoreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(() => loadState());

  useEffect(() => {
    persist(state);
  }, [state]);

  const getProduct = useCallback(
    (id: string) => state.products.find((p) => p.id === id),
    [state.products],
  );

  const getCategoryName = useCallback(
    (id: string) => state.categories.find((c) => c.id === id)?.name ?? "—",
    [state.categories],
  );

  const addProduct = useCallback((p: Omit<Product, "id">) => {
    setState((s) => ({
      ...s,
      products: [...s.products, { ...p, id: uid() }],
    }));
  }, []);

  const updateProduct = useCallback((id: string, p: Omit<Product, "id">) => {
    setState((s) => ({
      ...s,
      products: s.products.map((x) => (x.id === id ? { ...p, id } : x)),
    }));
  }, []);

  const deleteProduct = useCallback((id: string) => {
    setState((s) => ({
      ...s,
      products: s.products.filter((x) => x.id !== id),
    }));
  }, []);

  const addCategory = useCallback((name: string) => {
    const trimmed = name.trim();
    if (!trimmed) return;
    setState((s) => ({
      ...s,
      categories: [...s.categories, { id: uid(), name: trimmed }],
    }));
  }, []);

  const checkout = useCallback((cart: Map<string, number>, payment: PaymentMethod) => {
    let tx: Transaction | null = null;
    setState((s) => {
      const items: Transaction["items"] = [];
      const nextProducts = s.products.map((p) => {
        const qty = cart.get(p.id) ?? 0;
        if (qty <= 0) return p;
        if (qty > p.stock) return p;
        items.push({ productId: p.id, name: p.name, price: p.price, qty });
        return { ...p, stock: p.stock - qty };
      });
      if (!items.length) return s;
      const total = items.reduce((acc, i) => acc + i.price * i.qty, 0);
      tx = {
        id: uid(),
        createdAt: new Date().toISOString(),
        items,
        total,
        payment,
      };
      return {
        ...s,
        products: nextProducts,
        transactions: [tx, ...s.transactions],
      };
    });
    return tx;
  }, []);

  const resetDemoData = useCallback(() => {
    const fresh = buildInitialState();
    setState(fresh);
    persist(fresh);
  }, []);

  const value = useMemo<StoreContextValue>(
    () => ({
      state,
      categories: state.categories,
      products: state.products,
      transactions: state.transactions,
      getProduct,
      getCategoryName,
      addProduct,
      updateProduct,
      deleteProduct,
      addCategory,
      checkout,
      resetDemoData,
    }),
    [
      state,
      getProduct,
      getCategoryName,
      addProduct,
      updateProduct,
      deleteProduct,
      addCategory,
      checkout,
      resetDemoData,
    ],
  );

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore(): StoreContextValue {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("useStore outside StoreProvider");
  return ctx;
}

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";

const AUTH_KEY = "pempek_novi_auth_v1";

type AuthState = {
  username: string | null;
};

function loadAuth(): AuthState {
  try {
    const raw = localStorage.getItem(AUTH_KEY);
    if (raw) {
      const j = JSON.parse(raw) as AuthState;
      if (j?.username) return { username: j.username };
    }
  } catch {
    /* ignore */
  }
  return { username: null };
}

function saveAuth(a: AuthState) {
  if (a.username) localStorage.setItem(AUTH_KEY, JSON.stringify(a));
  else localStorage.removeItem(AUTH_KEY);
}

type AuthContextValue = {
  username: string | null;
  login: (username: string, password: string) => boolean;
  logout: () => void;
};

const AuthContext = createContext<AuthContextValue | null>(null);

/** Demo: gunakan admin / admin */
export function AuthProvider({ children }: { children: ReactNode }) {
  const [username, setUsername] = useState<string | null>(() => loadAuth().username);

  const login = useCallback((u: string, p: string) => {
    const user = u.trim();
    const pass = p.trim();
    if (!user || !pass) return false;
    if (user === "admin" && pass === "admin") {
      setUsername(user);
      saveAuth({ username: user });
      return true;
    }
    return false;
  }, []);

  const logout = useCallback(() => {
    setUsername(null);
    saveAuth({ username: null });
  }, []);

  const value = useMemo(
    () => ({ username, login, logout }),
    [username, login, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth outside AuthProvider");
  return ctx;
}

