import { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useStore } from "../context/StoreContext";

export default function ProductForm() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const nav = useNavigate();
  const { categories, getProduct, addProduct, updateProduct, addCategory } = useStore();

  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [stock, setStock] = useState("");
  const [categoryId, setCategoryId] = useState(categories[0]?.id ?? "");
  const [description, setDescription] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [newCat, setNewCat] = useState("");

  useEffect(() => {
    if (!isEdit || !id) return;
    const p = getProduct(id);
    if (!p) return;
    setName(p.name);
    setPrice(String(p.price));
    setStock(String(p.stock));
    setCategoryId(p.categoryId);
    setDescription(p.description);
    setImageUrl(p.imageUrl);
  }, [isEdit, id, getProduct]);

  useEffect(() => {
    if (!categoryId && categories[0]) setCategoryId(categories[0].id);
  }, [categories, categoryId]);

  function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = () => setImageUrl(String(r.result));
    r.readAsDataURL(f);
  }

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const pr = Number(price.replace(/\D/g, "")) || 0;
    const st = Number(stock.replace(/\D/g, "")) || 0;
    if (!name.trim()) return;
    let cat = categoryId;
    if (newCat.trim()) {
      addCategory(newCat.trim());
      /* category list updates next render — pick last matching name */
      /* simpler: addCategory then we need new id - change addCategory to return id */
    }
    /* handle new category: addCategory doesn't return id - useEffect hack or fix store */

    if (newCat.trim()) {
      addCategory(newCat.trim());
    }

    const effectiveCat =
      newCat.trim() && categories.every((c) => c.name !== newCat.trim())
        ? undefined
        : categoryId;

    /* After addCategory, state async - for simplicity require user to pick category OR we sync: */
    if (newCat.trim()) {
      addCategory(newCat.trim());
      setNewCat("");
      alert("Kategori baru ditambahkan. Pilih kategori di daftar, lalu simpan lagi.");
      return;
    }

    const payload = {
      name: name.trim(),
      price: pr,
      stock: st,
      categoryId: cat,
      description: description.trim(),
      imageUrl: imageUrl.trim() || "https://picsum.photos/seed/placeholder/400/300",
    };

    if (isEdit && id) updateProduct(id, payload);
    else addProduct(payload);
    nav("/produk/kelola");
  }

  return (
    <div className="page">
      <h1 style={{ margin: "0 0 1rem", fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>
        {isEdit ? "Edit Produk" : "Tambah Produk"}
      </h1>

      <form onSubmit={onSubmit} className="card" style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <div>
          <span className="label">Gambar Produk</span>
          <div
            style={{
              border: "2px dashed rgba(139,94,60,0.35)",
              borderRadius: 14,
              padding: "1rem",
              textAlign: "center",
              background: "var(--color-cream-2)",
            }}
          >
            {imageUrl ? (
              <img src={imageUrl} alt="" style={{ maxWidth: "100%", maxHeight: 160, borderRadius: 12 }} />
            ) : (
              <span style={{ color: "var(--color-muted)", fontSize: "0.9rem" }}>Unggah gambar</span>
            )}
            <input type="file" accept="image/*" onChange={onFile} style={{ marginTop: "0.75rem" }} />
          </div>
        </div>

        <div>
          <label className="label" htmlFor="nm">
            Nama Produk
          </label>
          <input id="nm" className="input" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
          <div>
            <label className="label" htmlFor="hg">
              Harga (Rp)
            </label>
            <input id="hg" className="input" inputMode="numeric" value={price} onChange={(e) => setPrice(e.target.value)} required />
          </div>
          <div>
            <label className="label" htmlFor="st">
              Stok
            </label>
