import { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useStore } from "../context/StoreContext";

export default function ProductForm() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const nav = useNavigate();
  const { categories, getProduct, addProduct, updateProduct, addCategory } = useStore();

  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [stock, setStock] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [description, setDescription] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [newCat, setNewCat] = useState("");

  useEffect(() => {
    if (!isEdit || !id) return;
    const p = getProduct(id);
    if (!p) return;
    setName(p.name);
    setPrice(String(p.price));
    setStock(String(p.stock));
    setCategoryId(p.categoryId);
    setDescription(p.description);
    setImageUrl(p.imageUrl);
  }, [isEdit, id, getProduct]);

  useEffect(() => {
    if (!categoryId && categories[0]) setCategoryId(categories[0].id);
  }, [categories, categoryId]);

  function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = () => setImageUrl(String(r.result));
    r.readAsDataURL(f);
  }

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const pr = Number(price.replace(/\D/g, "")) || 0;
    const st = Number(stock.replace(/\D/g, "")) || 0;
    if (!name.trim()) return;

    let cat = categoryId;
    if (newCat.trim()) {
      const nid = addCategory(newCat.trim());
      if (nid) cat = nid;
    }

    const payload = {
      name: name.trim(),
      price: pr,
      stock: st,
      categoryId: cat,
      description: description.trim(),
      imageUrl: imageUrl.trim() || "https://picsum.photos/seed/placeholder/400/300",
    };

    if (isEdit && id) updateProduct(id, payload);
    else addProduct(payload);
    nav("/produk/kelola");
  }

  return (
    <div className="page">
      <h1 style={{ margin: "0 0 1rem", fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>
        {isEdit ? "Edit Produk" : "Tambah Produk"}
      </h1>

      <form onSubmit={onSubmit} className="card" style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <div>
          <span className="label">Gambar Produk</span>
          <div
            style={{
              border: "2px dashed rgba(139,94,60,0.35)",
              borderRadius: 14,
              padding: "1rem",
              textAlign: "center",
              background: "var(--color-cream-2)",
            }}
          >
            {imageUrl ? (
              <img src={imageUrl} alt="" style={{ maxWidth: "100%", maxHeight: 160, borderRadius: 12 }} />
            ) : (
              <span style={{ color: "var(--color-muted)", fontSize: "0.9rem" }}>Unggah gambar</span>
            )}
            <input type="file" accept="image/*" onChange={onFile} style={{ marginTop: "0.75rem" }} />
          </div>
        </div>

        <div>
          <label className="label" htmlFor="nm">
            Nama Produk
          </label>
          <input id="nm" className="input" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
          <div>
            <label className="label" htmlFor="hg">
              Harga (Rp)
            </label>
            <input id="hg" className="input" inputMode="numeric" value={price} onChange={(e) => setPrice(e.target.value)} required />
          </div>
          <div>
            <label className="label" htmlFor="st">
              Stok
            </label>
            <input id="st" className="input" inputMode="numeric" value={stock} onChange={(e) => setStock(e.target.value)} required />
          </div>
        </div>

        <div>
          <label className="label" htmlFor="cat">
            Kategori
          </label>
          <select id="cat" className="input" value={categoryId} onChange={(e) => setCategoryId(e.target.value)}>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="label" htmlFor="ncat">
            Kategori baru (opsional)
          </label>
          <input
            id="ncat"
            className="input"
            placeholder="Isi untuk menambah kategori sekaligus"
            value={newCat}
            onChange={(e) => setNewCat(e.target.value)}
          />
        </div>

        <div>
          <label className="label" htmlFor="desc">
            Deskripsi
          </label>
          <textarea id="desc" className="input" rows={3} value={description} onChange={(e) => setDescription(e.target.value)} />
        </div>

        <button type="submit" className="btn btn--primary btn--block">
          Simpan
        </button>
      </form>

      <Link to="/produk/kelola" style={{ display: "block", marginTop: "1rem", textAlign: "center", color: "var(--color-muted)" }}>
        Batal
      </Link>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useStore } from "../context/StoreContext";
import type { PaymentMethod } from "../types";
import { formatIdr } from "../utils";

export default function Transaction() {
  const { products, checkout } = useStore();
  const nav = useNavigate();
  const [cart, setCart] = useState<Record<string, number>>({});
  const [payment, setPayment] = useState<PaymentMethod>("cash");

  const lines = useMemo(() => {
    return products
      .map((p) => ({ p, q: cart[p.id] ?? 0 }))
      .filter((x) => x.q > 0);
  }, [products, cart]);

  const total = useMemo(() => lines.reduce((s, x) => s + x.p.price * x.q, 0), [lines]);

  function setQty(pid: string, q: number) {
    setCart((c) => {
      const next = { ...c };
      if (q <= 0) delete next[pid];
      else next[pid] = q;
      return next;
    });
  }

  function bump(pid: string, delta: number) {
    const p = products.find((x) => x.id === pid);
    if (!p) return;
    const cur = cart[pid] ?? 0;
    const next = Math.max(0, Math.min(p.stock, cur + delta));
    setQty(pid, next);
  }

  function onPay() {
    const m = new Map<string, number>();
    for (const [k, v] of Object.entries(cart)) {
      if (v > 0) m.set(k, v);
    }
    const tx = checkout(m, payment);
    if (!tx) {
      alert("Keranjang kosong atau stok tidak mencukupi.");
      return;
    }
    nav(`/struk/${tx.id}`, { replace: true });
  }

  return (
    <div className="page">
      <header style={{ marginBottom: "1rem" }}>
        <h1 style={{ margin: 0, fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>Transaksi</h1>
        <Link to="/riwayat" style={{ fontSize: "0.85rem", color: "var(--color-primary)" }}>
          Riwayat transaksi →
        </Link>
      </header>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))",
          gap: "0.65rem",
          marginBottom: "1rem",
        }}
      >
        {products.map((p) => {
          const q = cart[p.id] ?? 0;
          return (
            <div key={p.id} className="card" style={{ padding: "0.6rem" }}>
              <div
                style={{
                  aspectRatio: "1/1",
                  borderRadius: 12,
                  background: "#ddd",
                  backgroundImage: p.imageUrl ? `url(${p.imageUrl})` : undefined,
                  backgroundSize: "cover",
                  marginBottom: "0.45rem",
                }}
              />
              <div style={{ fontWeight: 700, fontSize: "0.82rem", lineHeight: 1.2 }}>{p.name}</div>
              <div style={{ fontSize: "0.75rem", color: "var(--color-muted)" }}>{formatIdr(p.price)}</div>
              <div style={{ fontSize: "0.72rem", color: "var(--color-muted)" }}>Stok: {p.stock}</div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "0.45rem" }}>
                <button type="button" className="btn btn--ghost" style={{ padding: "0.35rem 0.55rem" }} onClick={() => bump(p.id, -1)}>
                  −
                </button>
                <span style={{ fontWeight: 700 }}>{q}</span>
                <button type="button" className="btn btn--ghost" style={{ padding: "0.35rem 0.55rem" }} onClick={() => bump(p.id, 1)}>
                  +
                </button>
              </div>
            </div>
          );
        })}
      </div>

      <div className="card" style={{ marginBottom: "5rem" }}>
        <div style={{ fontWeight: 700, marginBottom: "0.65rem", color: "var(--color-primary-dark)" }}>Ringkasan</div>
        {lines.length === 0 ? (
          <p style={{ margin: 0, color: "var(--color-muted)", fontSize: "0.9rem" }}>Belum ada item.</p>
        ) : (
          <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
            {lines.map(({ p, q }) => (
              <li key={p.id} style={{ display: "flex", justifyContent: "space-between", padding: "0.35rem 0", fontSize: "0.9rem" }}>
                <span>
                  {p.name} × {q}
                </span>
                <span style={{ fontWeight: 600 }}>{formatIdr(p.price * q)}</span>
              </li>
            ))}
          </ul>
        )}
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: "0.75rem", fontWeight: 800, fontSize: "1.05rem" }}>
          <span>Total</span>
          <span style={{ color: "var(--color-primary)" }}>{formatIdr(total)}</span>
        </div>

        <div style={{ marginTop: "1rem" }}>
          <span className="label">Metode pembayaran</span>
          <div style={{ display: "flex", gap: "0.5rem" }}>
            <button
              type="button"
              className="btn"
              style={{
                flex: 1,
                background: payment === "cash" ? "var(--color-primary)" : "rgba(139,94,60,0.12)",
                color: payment === "cash" ? "#fff" : "var(--color-primary-dark)",
              }}
              onClick={() => setPayment("cash")}
            >
              Tunai
            </button>
            <button
              type="button"
              className="btn"
              style={{
                flex: 1,
                background: payment === "transfer" ? "var(--color-primary)" : "rgba(139,94,60,0.12)",
                color: payment === "transfer" ? "#fff" : "var(--color-primary-dark)",
              }}
              onClick={() => setPayment("transfer")}
            >
              Transfer
            </button>
          </div>
        </div>

        <button type="button" className="btn btn--primary btn--block" style={{ marginTop: "1rem" }} onClick={onPay} disabled={lines.length === 0}>
          Bayar
        </button>
      </div>
    </div>
  );
}

