import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { DEFAULT_SETTINGS, normalizeAppState } from "../state/migrate";
import type { AppState, Category, OutletSettings, PaymentMethod, Product, Transaction } from "../types";

const STORAGE_KEY = "pempek_novi_store_v1";

function uid(): string {
  return crypto.randomUUID();
}

const img = (seed: number) => `https://picsum.photos/seed/pempeknovi${seed}/400/300`;

function product(
  id: string,
  sku: string,
  name: string,
  price: number,
  stock: number,
  categoryId: string,
  description: string,
  imageUrl: string,
  costRatio = 0.56,
): Product {
  return {
    id,
    sku,
    name,
    price,
    costPrice: Math.max(0, Math.round(price * costRatio)),
    stock,
    categoryId,
    description,
    imageUrl,
  };
}

function buildInitialState(): AppState {
  const catPempek: Category = { id: "c1", name: "Pempek" };
  const catMinuman: Category = { id: "c2", name: "Minuman" };
  const categories: Category[] = [catPempek, catMinuman];

  const products: Product[] = [
    product("p1", "PK-KS-01", "Pempek Kapal Selam", 18000, 40, "c1", "Telur di dalam adonan ikan, khas Palembang.", img(1)),
    product("p2", "PK-LJ-01", "Pempek Lenjer", 12000, 55, "c1", "Bentuk panjang, tekstur kenyal.", img(2)),
    product("p3", "PK-AD-01", "Pempek Adaan", 15000, 48, "c1", "Bulat dengan ebi di tengah.", img(3)),
    product("p4", "PK-TK-01", "Tekwan", 14000, 35, "c1", "Sup bening dengan suiran ikan.", img(4)),
    product("p5", "MN-EJ-01", "Es Jeruk", 8000, 100, "c2", "Segar, peras jeruk lokal.", img(5), 0.5),
    product("p6", "MN-TM-01", "Teh Manis", 5000, 120, "c2", "Teh tubruk dingin.", img(6), 0.48),
  ];

  const byId = new Map(products.map((p) => [p.id, p]));

  const now = new Date();
  const mkTx = (daysAgo: number, specs: { productId: string; qty: number }[], payment: PaymentMethod): Transaction => {
    const d = new Date(now);
    d.setDate(d.getDate() - daysAgo);
    d.setHours(10 + (daysAgo % 5), 30, 0, 0);
    const items = specs.map(({ productId, qty }) => {
      const p = byId.get(productId)!;
      return {
        productId,
        name: p.name,
        price: p.price,
        qty,
        unitCost: p.costPrice,
      };
    });
    const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
    return {
      id: uid(),
      createdAt: d.toISOString(),
      items,
      subtotal,
      discount: 0,
      tax: 0,
      grandTotal: subtotal,
      payment,
    };
  };

  const transactions: Transaction[] = [
    mkTx(0, [{ productId: "p1", qty: 2 }], "cash"),
    mkTx(0, [{ productId: "p3", qty: 3 }], "transfer"),
    mkTx(1, [{ productId: "p2", qty: 4 }], "cash"),
    mkTx(2, [{ productId: "p4", qty: 2 }], "transfer"),
    mkTx(5, [{ productId: "p1", qty: 1 }], "cash"),
    mkTx(8, [{ productId: "p5", qty: 3 }], "cash"),
    mkTx(12, [{ productId: "p2", qty: 6 }], "transfer"),
    mkTx(20, [{ productId: "p3", qty: 2 }], "cash"),
    mkTx(35, [{ productId: "p1", qty: 5 }], "transfer"),
    mkTx(50, [{ productId: "p4", qty: 3 }], "cash"),
  ];

  return { categories, products, transactions, settings: { ...DEFAULT_SETTINGS } };
}

function loadState(): AppState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as unknown;
      const migrated = normalizeAppState(parsed);
      if (migrated.products.length) return migrated;
    }
  } catch {
    /* ignore */
  }
  return buildInitialState();
}

function persist(state: AppState) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

type StoreContextValue = {
  state: AppState;
  settings: OutletSettings;
  categories: Category[];
  products: Product[];
  transactions: Transaction[];
  getProduct: (id: string) => Product | undefined;
  getCategoryName: (id: string) => string;
  addProduct: (p: Omit<Product, "id">) => void;
  updateProduct: (id: string, p: Omit<Product, "id">) => void;
  deleteProduct: (id: string) => void;
  addCategory: (name: string) => string | null;
  updateSettings: (patch: Partial<OutletSettings>) => void;
  checkout: (cart: Map<string, number>, payment: PaymentMethod, discount: number) => Transaction | null;
  resetDemoData: () => void;
};

const StoreContext = createContext<StoreContextValue | null>(null);

export function StoreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(() => loadState());

  useEffect(() => {
    persist(state);
  }, [state]);

  const getProduct = useCallback(
    (id: string) => state.products.find((p) => p.id === id),
    [state.products],
  );

  const getCategoryName = useCallback(
    (id: string) => state.categories.find((c) => c.id === id)?.name ?? "—",
    [state.categories],
  );

  const addProduct = useCallback((p: Omit<Product, "id">) => {
    setState((s) => ({
      ...s,
      products: [...s.products, { ...p, id: uid() }],
    }));
  }, []);

  const updateProduct = useCallback((id: string, p: Omit<Product, "id">) => {
    setState((s) => ({
      ...s,
      products: s.products.map((x) => (x.id === id ? { ...p, id } : x)),
    }));
  }, []);

  const deleteProduct = useCallback((id: string) => {
    setState((s) => ({
      ...s,
      products: s.products.filter((x) => x.id !== id),
    }));
  }, []);

  const addCategory = useCallback((name: string): string | null => {
    const trimmed = name.trim();
    if (!trimmed) return null;
    const cid = uid();
    setState((s) => ({
      ...s,
      categories: [...s.categories, { id: cid, name: trimmed }],
    }));
    return cid;
  }, []);

  const updateSettings = useCallback((patch: Partial<OutletSettings>) => {
    setState((s) => ({
      ...s,
      settings: {
        ...s.settings,
        ...patch,
        taxPercent:
          typeof patch.taxPercent === "number"
            ? Math.min(100, Math.max(0, patch.taxPercent))
            : s.settings.taxPercent,
        lowStockThreshold:
          typeof patch.lowStockThreshold === "number"
            ? Math.max(0, Math.floor(patch.lowStockThreshold))
            : s.settings.lowStockThreshold,
      },
    }));
  }, []);

  const checkout = useCallback((cart: Map<string, number>, payment: PaymentMethod, discountRaw: number) => {
    let tx: Transaction | null = null;
    setState((s) => {
      const items: Transaction["items"] = [];
      for (const p of s.products) {
        const qty = cart.get(p.id) ?? 0;
        if (qty <= 0) continue;
        if (qty > p.stock) return s;
        items.push({
          productId: p.id,
          name: p.name,
          price: p.price,
          qty,
          unitCost: p.costPrice,
        });
      }
      if (!items.length) return s;

      const subtotal = items.reduce((acc, i) => acc + i.price * i.qty, 0);
      const discount = Math.min(Math.max(0, Math.floor(discountRaw)), subtotal);
      const afterDisc = subtotal - discount;
      const tax = Math.round((afterDisc * s.settings.taxPercent) / 100);
      const grandTotal = afterDisc + tax;

      const nextProducts = s.products.map((p) => {
        const qty = cart.get(p.id) ?? 0;
        if (qty <= 0) return p;
        return { ...p, stock: p.stock - qty };
      });

      tx = {
        id: uid(),
        createdAt: new Date().toISOString(),
        items,
        subtotal,
        discount,
        tax,
        grandTotal,
        payment,
      };

      return {
        ...s,
        products: nextProducts,
        transactions: [tx, ...s.transactions],
      };
    });
    return tx;
  }, []);

  const resetDemoData = useCallback(() => {
    const fresh = buildInitialState();
    setState(fresh);
    persist(fresh);
  }, []);

  const value = useMemo<StoreContextValue>(
    () => ({
      state,
      settings: state.settings,
      categories: state.categories,
      products: state.products,
      transactions: state.transactions,
      getProduct,
      getCategoryName,
      addProduct,
      updateProduct,
      deleteProduct,
      addCategory,
      updateSettings,
      checkout,
      resetDemoData,
    }),
    [
      state,
      getProduct,
      getCategoryName,
      addProduct,
      updateProduct,
      deleteProduct,
      addCategory,
      updateSettings,
      checkout,
      resetDemoData,
    ],
  );

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore(): StoreContextValue {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("useStore outside StoreProvider");
  return ctx;
}

