import { useState } from "react";
import { Link } from "react-router-dom";
import { useStore } from "../context/StoreContext";
import { useToast } from "../context/ToastContext";

export default function Settings() {
  const { settings, updateSettings, resetDemoData } = useStore();
  const { push } = useToast();

  const [outletName, setOutletName] = useState(settings.outletName);
  const [address, setAddress] = useState(settings.address);
  const [phone, setPhone] = useState(settings.phone);
  const [taxPercent, setTaxPercent] = useState(String(settings.taxPercent));
  const [lowStockThreshold, setLowStockThreshold] = useState(String(settings.lowStockThreshold));

  function save(e: React.FormEvent) {
    e.preventDefault();
    const tax = Number(taxPercent.replace(",", ".")) || 0;
    const low = Number(lowStockThreshold.replace(/\D/g, "")) || 0;
    updateSettings({
      outletName: outletName.trim() || settings.outletName,
      address: address.trim(),
      phone: phone.trim(),
      taxPercent: tax,
      lowStockThreshold: low,
    });
    push("Pengaturan disimpan.", "success");
  }

  return (
    <div className="page">
      <h1 style={{ margin: "0 0 1rem", fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>Pengaturan</h1>

      <form onSubmit={save} className="card" style={{ display: "flex", flexDirection: "column", gap: "1rem", marginBottom: "1rem" }}>
        <div>
          <label className="label" htmlFor="on">
            Nama outlet (struk)
          </label>
          <input id="on" className="input" value={outletName} onChange={(e) => setOutletName(e.target.value)} />
        </div>
        <div>
          <label className="label" htmlFor="ad">
