        <button type="submit" className="btn btn--primary btn--block">
          Simpan pengaturan
        </button>
      </form>

      <div className="card" style={{ border: "1px solid rgba(198,40,40,0.25)" }}>
        <div style={{ fontWeight: 700, marginBottom: "0.5rem", color: "var(--color-danger)" }}>Zona bahaya</div>
        <p style={{ margin: "0 0 0.75rem", fontSize: "0.85rem", color: "var(--color-muted)" }}>
          Mengembalikan data demo akan menimpa produk, transaksi, dan kategori di perangkat ini.
        </p>
        <button
          type="button"
          className="btn btn--danger btn--block"
          onClick={() => {
            if (confirm("Reset ke data demo? Data saat ini akan hilang.")) {
              resetDemoData();
              setOutletName(DEFAULT_SETTINGS.outletName);
              setAddress(DEFAULT_SETTINGS.address);
              setPhone(DEFAULT_SETTINGS.phone);
