import { Link } from "react-router-dom";
import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { useAuth } from "../context/AuthContext";
import { useStore } from "../context/StoreContext";
import { formatIdr, startOfDay, transactionProfit } from "../utils";

function monthKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

function last6MonthLabels(): string[] {
  const out: string[] = [];
  const d = new Date();
  for (let i = 5; i >= 0; i--) {
    const x = new Date(d.getFullYear(), d.getMonth() - i, 1);
    out.push(monthKey(x));
  }
  return out;
}

export default function Dashboard() {
  const { transactions, products, settings } = useStore();
  const { logout, username } = useAuth();

  const now = new Date();
  const t0 = startOfDay(now).getTime();
  const t1 = t0 - 86400000;

  let todayRev = 0;
  let todayCount = 0;
  let yestRev = 0;
  let todayProfit = 0;
  for (const tx of transactions) {
    const ts = new Date(tx.createdAt).getTime();
    if (ts >= t0) {
      todayRev += tx.grandTotal;
      todayCount += 1;
      todayProfit += transactionProfit(tx);
    } else if (ts >= t1 && ts < t0) {
      yestRev += tx.grandTotal;
    }
  }

  const pct =
    yestRev > 0 ? Math.round(((todayRev - yestRev) / yestRev) * 100) : todayRev > 0 ? 100 : 0;

  const labels = last6MonthLabels();
  const byMonthOmzet = new Map<string, number>();
  const byMonthProfit = new Map<string, number>();
  for (const k of labels) {
    byMonthOmzet.set(k, 0);
    byMonthProfit.set(k, 0);
  }
  for (const tx of transactions) {
    const k = monthKey(new Date(tx.createdAt));
    if (byMonthOmzet.has(k)) {
      byMonthOmzet.set(k, (byMonthOmzet.get(k) ?? 0) + tx.grandTotal);
      byMonthProfit.set(k, (byMonthProfit.get(k) ?? 0) + transactionProfit(tx));
    }
  }
  const chartData = labels.map((k) => ({
    name: k.slice(5),
    omzet: byMonthOmzet.get(k) ?? 0,
    laba: byMonthProfit.get(k) ?? 0,
  }));

  const recent = transactions.slice(0, 6);

  const lowStock = products
    .filter((p) => p.stock <= settings.lowStockThreshold)
    .sort((a, b) => a.stock - b.stock);

  return (
    <div className="page">
      <header
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: "1rem",
        }}
      >
        <h1 style={{ margin: 0, fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>Dashboard</h1>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <Link to="/pengaturan" className="btn btn--ghost" style={{ padding: "0.45rem 0.65rem", fontSize: "0.85rem" }} title="Pengaturan">
            ⚙
          </Link>
          <span style={{ fontSize: "0.8rem", color: "var(--color-muted)", display: "none" }} className="show-desktop-user">
            {username}
          </span>
          <button
            type="button"
            className="btn btn--ghost show-mobile-logout"
            onClick={() => {
              if (confirm("Keluar dari aplikasi?")) logout();
            }}
            aria-label="Keluar"
          >
            ⎋
          </button>
        </div>
      </header>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "0.75rem",
          marginBottom: "1rem",
        }}
      >
        <div className="card">
          <div style={{ fontSize: "0.75rem", color: "var(--color-muted)", fontWeight: 600 }}>Pendapatan Hari Ini</div>
          <div style={{ fontSize: "1.15rem", fontWeight: 700, marginTop: "0.35rem" }}>{formatIdr(todayRev)}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-success)", marginTop: "0.25rem" }}>
            {pct >= 0 ? "+" : ""}
            {pct}% vs kemarin
          </div>
        </div>
        <div className="card">
          <div style={{ fontSize: "0.75rem", color: "var(--color-muted)", fontWeight: 600 }}>Total Transaksi</div>
          <div style={{ fontSize: "1.35rem", fontWeight: 700, marginTop: "0.35rem" }}>{todayCount}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-muted)", marginTop: "0.25rem" }}>Hari ini</div>
        </div>
        <div className="card">
          <div style={{ fontSize: "0.75rem", color: "var(--color-muted)", fontWeight: 600 }}>Laba kotor (est.)</div>
          <div style={{ fontSize: "1.1rem", fontWeight: 700, marginTop: "0.35rem", color: "var(--color-success)" }}>{formatIdr(todayProfit)}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-muted)", marginTop: "0.25rem" }}>Hari ini</div>
        </div>
        <div className="card">
          <div style={{ fontSize: "0.75rem", color: "var(--color-muted)", fontWeight: 600 }}>Stok menipis</div>
          <div style={{ fontSize: "1.35rem", fontWeight: 700, marginTop: "0.35rem", color: lowStock.length ? "#e65100" : "var(--color-text)" }}>{lowStock.length}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-muted)", marginTop: "0.25rem" }}>≤ {settings.lowStockThreshold} unit</div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: "1rem" }}>
        <div style={{ fontWeight: 700, marginBottom: "0.75rem", color: "var(--color-primary-dark)" }}>Grafik Omzet &amp; Laba</div>
        <div style={{ width: "100%", height: 240 }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(139,94,60,0.15)" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="#6b5d4f" />
              <YAxis tick={{ fontSize: 11 }} stroke="#6b5d4f" tickFormatter={(v) => `${Math.round(v / 1000)}k`} />
              <Tooltip
                formatter={(value: number, name: string) => [formatIdr(value), name === "omzet" ? "Omzet" : "Laba kotor"]}
              />
              <Legend formatter={(v) => (v === "omzet" ? "Omzet" : "Laba kotor")} />
              <Line type="monotone" dataKey="omzet" name="omzet" stroke="#8b5e3c" strokeWidth={2} dot={{ r: 3 }} />
              <Line type="monotone" dataKey="laba" name="laba" stroke="#2e7d32" strokeWidth={2} dot={{ r: 3 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {lowStock.length > 0 ? (
        <div className="card" style={{ marginBottom: "1rem", border: "1px solid rgba(230,81,0,0.35)", background: "#fff8f0" }}>
          <div style={{ fontWeight: 700, marginBottom: "0.5rem", color: "#bf360c" }}>Peringatan stok</div>
          <ul style={{ margin: 0, paddingLeft: "1.1rem", fontSize: "0.88rem", color: "var(--color-text)" }}>
            {lowStock.map((p) => (
              <li key={p.id} style={{ marginBottom: "0.25rem" }}>
                <Link to={`/produk/${p.id}/edit`} style={{ color: "var(--color-primary-dark)", fontWeight: 600 }}>
                  {p.name}
                </Link>{" "}
                — sisa <strong>{p.stock}</strong>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <div style={{ fontWeight: 700, marginBottom: "0.65rem", color: "var(--color-primary-dark)" }}>Menu Cepat</div>
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.5rem",
          marginBottom: "1.25rem",
        }}
      >
        <Quick to="/produk" label="Produk" bg="#e8f5e9" emoji="▣" style={{ flex: "1 1 22%", minWidth: 72 }} />
        <Quick to="/produk/kelola" label="Kelola" bg="#fff3e0" emoji="✎" style={{ flex: "1 1 22%", minWidth: 72 }} />
        <Quick to="/transaksi" label="Transaksi" bg="#e3f2fd" emoji="◇" style={{ flex: "1 1 22%", minWidth: 72 }} />
        <Quick to="/laporan" label="Laporan" bg="#fce4ec" emoji="▤" style={{ flex: "1 1 22%", minWidth: 72 }} />
        <Quick to="/pengaturan" label="Set" bg="#efebe9" emoji="⚙" style={{ flex: "1 1 22%", minWidth: 72 }} />
      </div>

      <div style={{ fontWeight: 700, marginBottom: "0.65rem", color: "var(--color-primary-dark)" }}>Aktivitas Terbaru</div>
      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
        {recent.length === 0 ? (
          <p style={{ padding: "1rem", margin: 0, color: "var(--color-muted)" }}>Belum ada transaksi.</p>
        ) : (
          <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
            {recent.map((tx) => (
              <li
                key={tx.id}
                style={{
                  padding: "0.85rem 1rem",
                  borderBottom: "1px solid rgba(139,94,60,0.08)",
                  display: "flex",
                  justifyContent: "space-between",
                  gap: "0.75rem",
                  alignItems: "center",
                }}
              >
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontWeight: 600, fontSize: "0.9rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {tx.items.map((i) => `${i.name} (${i.qty})`).join(", ")}
                  </div>
                  <div style={{ fontSize: "0.75rem", color: "var(--color-muted)" }}>
                    {new Date(tx.createdAt).toLocaleString("id-ID", { dateStyle: "short", timeStyle: "short" })}
                  </div>
                </div>
                <div style={{ fontWeight: 700, color: "var(--color-primary)", flexShrink: 0 }}>{formatIdr(tx.grandTotal)}</div>
              </li>
            ))}
          </ul>
        )}
      </div>

      <style>{`
        @media (min-width: 900px) {
          .show-mobile-logout { display: none !important; }
          .show-desktop-user { display: inline !important; }
        }
      `}</style>
    </div>
  );
}

function Quick({
  to,
  label,
  bg,
  emoji,
  style,
}: {
  to: string;
  label: string;
  bg: string;
  emoji: string;
  style?: React.CSSProperties;
}) {
  return (
    <Link
      to={to}
      className="card"
      style={{
        textAlign: "center",
        padding: "0.65rem 0.25rem",
        background: bg,
        boxShadow: "0 4px 12px rgba(44,36,25,0.06)",
        textDecoration: "none",
        color: "inherit",
        ...style,
      }}
    >
      <div style={{ fontSize: "1.35rem" }} aria-hidden>
        {emoji}
      </div>
      <div style={{ fontSize: "0.65rem", fontWeight: 700, marginTop: "0.2rem", color: "var(--color-primary-dark)" }}>{label}</div>
    </Link>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useStore } from "../context/StoreContext";
import { useToast } from "../context/ToastContext";
import type { PaymentMethod } from "../types";
import { formatIdr } from "../utils";

export default function Transaction() {
  const { products, categories, checkout, settings, getCategoryName } = useStore();
  const nav = useNavigate();
  const { push } = useToast();
  const searchRef = useRef<HTMLInputElement>(null);

  const [cart, setCart] = useState<Record<string, number>>({});
  const [payment, setPayment] = useState<PaymentMethod>("cash");
  const [query, setQuery] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [discountStr, setDiscountStr] = useState("");

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "/") return;
      const t = e.target as HTMLElement | null;
      if (t && ["INPUT", "TEXTAREA", "SELECT"].includes(t.tagName)) return;
      e.preventDefault();
      searchRef.current?.focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const filteredProducts = useMemo(() => {
    const q = query.trim().toLowerCase();
    return products.filter((p) => {
      if (categoryId && p.categoryId !== categoryId) return false;
      if (!q) return true;
      return p.name.toLowerCase().includes(q) || p.sku.toLowerCase().includes(q);
    });
  }, [products, query, categoryId]);

  const lines = useMemo(() => {
    return products
      .map((p) => ({ p, q: cart[p.id] ?? 0 }))
      .filter((x) => x.q > 0);
  }, [products, cart]);

  const subtotal = useMemo(() => lines.reduce((s, x) => s + x.p.price * x.q, 0), [lines]);
  const discount = Math.min(Math.max(0, Math.floor(Number(discountStr.replace(/\D/g, "")) || 0)), subtotal);
  const afterDisc = subtotal - discount;
  const tax = Math.round((afterDisc * settings.taxPercent) / 100);
  const grandPreview = afterDisc + tax;

  function setQty(pid: string, q: number) {
    setCart((c) => {
      const next = { ...c };
      if (q <= 0) delete next[pid];
      else next[pid] = q;
      return next;
    });
  }

  function bump(pid: string, delta: number) {
    const p = products.find((x) => x.id === pid);
    if (!p) return;
    const cur = cart[pid] ?? 0;
    const next = Math.max(0, Math.min(p.stock, cur + delta));
    setQty(pid, next);
  }

  function applyDiscPct(pct: number) {
    if (subtotal <= 0) return;
    setDiscountStr(String(Math.floor((subtotal * pct) / 100)));
  }

  function onPay() {
    const m = new Map<string, number>();
    for (const [k, v] of Object.entries(cart)) {
      if (v > 0) m.set(k, v);
    }
    const tx = checkout(m, payment, discount);
    if (!tx) {
      push("Keranjang kosong atau stok tidak mencukupi.", "error");
      return;
    }
    push("Transaksi berhasil.", "success");
    nav(`/struk/${tx.id}`, { replace: true });
  }

  return (
    <div className="page">
      <header style={{ marginBottom: "0.75rem" }}>
        <h1 style={{ margin: 0, fontSize: "1.35rem", color: "var(--color-primary-dark)" }}>Transaksi</h1>
        <Link to="/riwayat" style={{ fontSize: "0.85rem", color: "var(--color-primary)" }}>
          Riwayat transaksi →
        </Link>
      </header>

      <div className="card" style={{ marginBottom: "0.75rem", display: "flex", flexDirection: "column", gap: "0.65rem" }}>
        <div>
          <label className="label" htmlFor="sq">
            Cari produk / SKU <span style={{ fontWeight: 400, opacity: 0.85 }}>(tekan /)</span>
          </label>
          <input
            ref={searchRef}
            id="sq"
            className="input"
            placeholder="Contoh: lenjer, PK-"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
        <div>
          <label className="label" htmlFor="cf">
            Filter kategori
          </label>
          <select id="cf" className="input" value={categoryId} onChange={(e) => setCategoryId(e.target.value)}>
            <option value="">Semua</option>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))",
          gap: "0.65rem",
          marginBottom: "1rem",
        }}
      >
        {filteredProducts.map((p) => {
          const q = cart[p.id] ?? 0;
          return (
            <div key={p.id} className="card" style={{ padding: "0.6rem" }}>
              <div
                style={{
                  aspectRatio: "1/1",
                  borderRadius: 12,
                  background: "#ddd",
                  backgroundImage: p.imageUrl ? `url(${p.imageUrl})` : undefined,
                  backgroundSize: "cover",
                  marginBottom: "0.45rem",
                }}
              />
              <div style={{ fontWeight: 700, fontSize: "0.82rem", lineHeight: 1.2 }}>{p.name}</div>
              {p.sku ? (
                <div style={{ fontSize: "0.68rem", color: "var(--color-muted)" }}>{p.sku}</div>
              ) : null}
              <div style={{ fontSize: "0.72rem", color: "var(--color-muted)" }}>{getCategoryName(p.categoryId)}</div>
              <div style={{ fontSize: "0.75rem", color: "var(--color-muted)" }}>{formatIdr(p.price)}</div>
              <div style={{ fontSize: "0.72rem", color: "var(--color-muted)" }}>Stok: {p.stock}</div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "0.45rem" }}>
                <button type="button" className="btn btn--ghost" style={{ padding: "0.35rem 0.55rem" }} onClick={() => bump(p.id, -1)}>
                  −
                </button>
                <span style={{ fontWeight: 700 }}>{q}</span>
                <button type="button" className="btn btn--ghost" style={{ padding: "0.35rem 0.55rem" }} onClick={() => bump(p.id, 1)}>
                  +
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {filteredProducts.length === 0 ? (
        <p style={{ color: "var(--color-muted)", fontSize: "0.9rem" }}>Tidak ada produk yang cocok.</p>
      ) : null}

      <div className="card" style={{ marginBottom: "5rem" }}>
        <div style={{ fontWeight: 700, marginBottom: "0.65rem", color: "var(--color-primary-dark)" }}>Ringkasan</div>
        {lines.length === 0 ? (
          <p style={{ margin: 0, color: "var(--color-muted)", fontSize: "0.9rem" }}>Belum ada item.</p>
        ) : (
          <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
            {lines.map(({ p, q }) => (
              <li key={p.id} style={{ display: "flex", justifyContent: "space-between", padding: "0.35rem 0", fontSize: "0.9rem" }}>
                <span>
                  {p.name} × {q}
                </span>
                <span style={{ fontWeight: 600 }}>{formatIdr(p.price * q)}</span>
              </li>
            ))}
          </ul>
        )}

        <div style={{ display: "flex", justifyContent: "space-between", marginTop: "0.5rem", fontSize: "0.9rem" }}>
          <span>Subtotal</span>
          <span style={{ fontWeight: 600 }}>{formatIdr(subtotal)}</span>
        </div>

        <div style={{ marginTop: "0.85rem" }}>
          <label className="label" htmlFor="disc">
            Diskon (Rp)
          </label>
          <input id="disc" className="input" inputMode="numeric" placeholder="0" value={discountStr} onChange={(e) => setDiscountStr(e.target.value)} />
          <div style={{ display: "flex", gap: "0.35rem", marginTop: "0.4rem", flexWrap: "wrap" }}>
            <button type="button" className="btn btn--ghost" style={{ fontSize: "0.75rem", padding: "0.35rem 0.5rem" }} onClick={() => applyDiscPct(5)}>
              5%
            </button>
            <button type="button" className="btn btn--ghost" style={{ fontSize: "0.75rem", padding: "0.35rem 0.5rem" }} onClick={() => applyDiscPct(10)}>
              10%
            </button>
            <button type="button" className="btn btn--ghost" style={{ fontSize: "0.75rem", padding: "0.35rem 0.5rem" }} onClick={() => setDiscountStr("0")}>
              Hapus
            </button>
          </div>
        </div>

        {settings.taxPercent > 0 ? (
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: "0.5rem", fontSize: "0.9rem" }}>
            <span>Pajak ({settings.taxPercent}%)</span>
            <span style={{ fontWeight: 600 }}>{formatIdr(tax)}</span>
          </div>
        ) : null}

        <div style={{ display: "flex", justifyContent: "space-between", marginTop: "0.65rem", fontWeight: 800, fontSize: "1.05rem" }}>
          <span>Total bayar</span>
          <span style={{ color: "var(--color-primary)" }}>{formatIdr(grandPreview)}</span>
        </div>

        <div style={{ marginTop: "1rem" }}>
          <span className="label">Metode pembayaran</span>
          <div style={{ display: "flex", gap: "0.5rem" }}>
            <button
              type="button"
              className="btn"
              style={{
                flex: 1,
                background: payment === "cash" ? "var(--color-primary)" : "rgba(139,94,60,0.12)",
                color: payment === "cash" ? "#fff" : "var(--color-primary-dark)",
              }}
              onClick={() => setPayment("cash")}
            >
              Tunai
            </button>
            <button
              type="button"
              className="btn"
              style={{
                flex: 1,
                background: payment === "transfer" ? "var(--color-primary)" : "rgba(139,94,60,0.12)",
                color: payment === "transfer" ? "#fff" : "var(--color-primary-dark)",
              }}
              onClick={() => setPayment("transfer")}
            >
              Transfer
            </button>
          </div>
        </div>

        <button type="button" className="btn btn--primary btn--block" style={{ marginTop: "1rem" }} onClick={onPay} disabled={lines.length === 0}>
          Bayar
        </button>
      </div>
    </div>
  );
}

import { QRCodeSVG } from "qrcode.react";
import { Link, useParams } from "react-router-dom";
import { useStore } from "../context/StoreContext";
import { useToast } from "../context/ToastContext";
import { formatDate, formatIdr, orderIdDisplay } from "../utils";

export default function Receipt() {
  const { id } = useParams();
  const { transactions, settings } = useStore();
  const { push } = useToast();
  const tx = transactions.find((t) => t.id === id);

  const verifyUrl = typeof window !== "undefined" && id ? `${window.location.origin}/struk/${id}` : "";

  function doPrint() {
    window.print();
  }

  async function doShare() {
    if (!tx) return;
    const text = `Struk ${orderIdDisplay(tx.id)} — ${settings.outletName}\nTotal: ${formatIdr(tx.grandTotal)}`;
    try {
      if (navigator.share) {
        await navigator.share({ title: "Struk transaksi", text, url: verifyUrl });
      } else {
        await navigator.clipboard.writeText(`${text}\n${verifyUrl}`);
        push("Struk disalin ke clipboard.", "success");
      }
    } catch {
      /* user cancelled */
    }
  }

  if (!tx) {
    return (
      <div className="page">
        <p>Struk tidak ditemukan.</p>
        <Link to="/riwayat">Kembali ke riwayat</Link>
      </div>
    );
  }

  return (
    <div className="page">
      <div className="no-print" style={{ marginBottom: "1rem", display: "flex", gap: "0.5rem", flexWrap: "wrap" }}>
        <Link to="/riwayat" className="btn btn--ghost">
          ← Riwayat
        </Link>
        <button type="button" className="btn btn--primary" onClick={doPrint}>
          Cetak
        </button>
        <button type="button" className="btn btn--ghost" onClick={doPrint}>
          Simpan PDF
        </button>
        <button type="button" className="btn btn--ghost" onClick={doShare}>
          Bagikan
        </button>
      </div>

      <div className="card receipt-print" style={{ maxWidth: 400, margin: "0 auto" }}>
        <div style={{ textAlign: "center", marginBottom: "1rem" }}>
          <div style={{ fontWeight: 800, fontSize: "1.2rem", color: "var(--color-primary-dark)" }}>{settings.outletName}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-muted)", marginTop: "0.25rem" }}>{settings.address}</div>
          <div style={{ fontSize: "0.8rem", color: "var(--color-muted)" }}>{settings.phone}</div>
        </div>
        <div style={{ fontSize: "0.85rem", marginBottom: "0.75rem", color: "var(--color-muted)" }}>
          <div>ID: #{orderIdDisplay(tx.id)}</div>
          <div>{formatDate(tx.createdAt)}</div>
          <div>Bayar: {tx.payment === "cash" ? "Tunai" : "Transfer"}</div>
        </div>
        <div style={{ borderTop: "1px dashed rgba(139,94,60,0.35)", borderBottom: "1px dashed rgba(139,94,60,0.35)", padding: "0.75rem 0" }}>
          {tx.items.map((i) => (
            <div key={i.productId + i.name} style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.35rem", fontSize: "0.9rem" }}>
              <span>
                {i.name} ({i.qty} × {formatIdr(i.price)})
              </span>
              <span style={{ fontWeight: 600 }}>{formatIdr(i.price * i.qty)}</span>
            </div>
          ))}
        </div>
        <div style={{ marginTop: "0.65rem", fontSize: "0.9rem", display: "flex", flexDirection: "column", gap: "0.25rem" }}>
          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <span>Subtotal</span>
            <span>{formatIdr(tx.subtotal)}</span>
          </div>
          {tx.discount > 0 ? (
            <div style={{ display: "flex", justifyContent: "space-between", color: "var(--color-success)" }}>
              <span>Diskon</span>
              <span>−{formatIdr(tx.discount)}</span>
            </div>
          ) : null}
          {tx.tax > 0 ? (
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <span>Pajak</span>
              <span>{formatIdr(tx.tax)}</span>
            </div>
          ) : null}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: "0.85rem", fontWeight: 800, fontSize: "1.05rem" }}>
          <span>Total</span>
          <span>{formatIdr(tx.grandTotal)}</span>
        </div>
        <div style={{ display: "flex", justifyContent: "center", marginTop: "1.25rem" }}>
          <QRCodeSVG value={verifyUrl || tx.id} size={128} level="M" includeMargin />
        </div>
        <p style={{ textAlign: "center", fontSize: "0.75rem", color: "var(--color-muted)", marginTop: "0.5rem" }}>Scan untuk verifikasi</p>
      </div>
    </div>
  );
}

