/** Penyimpanan password lokal (demo / tanpa server). Bukan untuk produksi. */
const KEY = "pempek_novi_credentials_v1";

export type CredentialsFile = { passwords: Record<string, string> };

function load(): CredentialsFile {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return { passwords: {} };
    const j = JSON.parse(raw) as CredentialsFile;
    if (j && typeof j.passwords === "object" && j.passwords) return j;
  } catch {
    /* ignore */
  }
  return { passwords: {} };
}

function save(f: CredentialsFile) {
  localStorage.setItem(KEY, JSON.stringify(f));
}

/** Password bawaan jika belum pernah diubah lewat reset. */
export function defaultPassword(username: string): string | null {
  const u = username.trim().toLowerCase();
  if (u === "admin") return "admin";
  return null;
}

export function getStoredPassword(username: string): string | null {
  const u = username.trim().toLowerCase();
  const v = load().passwords[u];
  return typeof v === "string" ? v : null;
}

export function setStoredPassword(username: string, password: string) {
  const u = username.trim().toLowerCase();
  const f = load();
  f.passwords[u] = password;
  save(f);
}

export function verifyPassword(username: string, password: string): boolean {
  const u = username.trim().toLowerCase();
  const stored = getStoredPassword(u);
  if (stored !== null) return stored === password;
  const def = defaultPassword(u);
  return def !== null && def === password;
}

const SESSION_KEY = "pempek_pw_reset_session_v1";

export type ResetSession = {
  username: string;
  email: string;
  code: string;
  expiresAt: number;
};

const TTL_MS = 10 * 60 * 1000;

export function generateSixDigitCode(): string {
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  const n = buf[0]! % 1_000_000;
  return String(n).padStart(6, "0");
}

export function createResetSession(username: string, email: string, code: string): ResetSession {
  const session: ResetSession = {
    username: username.trim().toLowerCase(),
    email: email.trim(),
    code,
    expiresAt: Date.now() + TTL_MS,
  };
  sessionStorage.setItem(SESSION_KEY, JSON.stringify(session));
  return session;
}

export function readResetSession(): ResetSession | null {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    const j = JSON.parse(raw) as ResetSession;
    if (!j?.username || !j?.code || typeof j.expiresAt !== "number") return null;
    if (Date.now() > j.expiresAt) {
      clearResetSession();
      return null;
    }
    return j;
  } catch {
    return null;
  }
}

export function clearResetSession() {
  sessionStorage.removeItem(SESSION_KEY);
}

export function verifyCodeForUser(username: string, code: string): boolean {
  const s = readResetSession();
  if (!s) return false;
  const u = username.trim().toLowerCase();
  return s.username === u && s.code === code.trim();
}

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { setStoredPassword, verifyPassword } from "../auth/localCredentials";
import {
  clearResetSession,
  createResetSession,
  generateSixDigitCode,
  verifyCodeForUser,
} from "../auth/resetSession";

const AUTH_KEY = "pempek_novi_auth_v1";

type AuthState = {
  username: string | null;
};

function loadAuth(): AuthState {
  try {
    const raw = localStorage.getItem(AUTH_KEY);
    if (raw) {
      const j = JSON.parse(raw) as AuthState;
      if (j?.username) return { username: j.username };
    }
  } catch {
    /* ignore */
  }
  return { username: null };
}

function saveAuth(a: AuthState) {
  if (a.username) localStorage.setItem(AUTH_KEY, JSON.stringify(a));
  else localStorage.removeItem(AUTH_KEY);
}

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
}

type SendResetResult =
  | { ok: true; code: string }
  | { ok: false; error: string };

type CompleteResetResult = { ok: true } | { ok: false; error: string };

type AuthContextValue = {
  username: string | null;
  login: (username: string, password: string) => boolean;
  logout: () => void;
  /** Simulasi kirim kode (tanpa server email). Hanya akun demo `admin`. */
  sendPasswordResetCode: (username: string, email: string) => Promise<SendResetResult>;
  completePasswordReset: (username: string, code: string, newPassword: string) => CompleteResetResult;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [username, setUsername] = useState<string | null>(() => loadAuth().username);

  const login = useCallback((u: string, p: string) => {
    const user = u.trim().toLowerCase();
    const pass = p.trim();
    if (!user || !pass) return false;
    if (verifyPassword(user, pass)) {
      setUsername(user);
      saveAuth({ username: user });
      return true;
    }
    return false;
  }, []);

  const logout = useCallback(() => {
    setUsername(null);
    saveAuth({ username: null });
  }, []);

  const sendPasswordResetCode = useCallback(async (u: string, email: string): Promise<SendResetResult> => {
    const user = u.trim().toLowerCase();
    if (user !== "admin") {
      return { ok: false, error: "Username tidak terdaftar. Hanya akun admin yang didukung pada aplikasi demo ini." };
    }
    if (!isValidEmail(email)) {
      return { ok: false, error: "Alamat email tidak valid." };
    }
    await new Promise((r) => setTimeout(r, 700));
    const code = generateSixDigitCode();
    createResetSession(user, email.trim(), code);
    return { ok: true, code };
  }, []);

  const completePasswordReset = useCallback((u: string, code: string, newPassword: string): CompleteResetResult => {
    const user = u.trim().toLowerCase();
    if (user !== "admin") return { ok: false, error: "Username tidak valid." };
    const pass = newPassword.trim();
    if (pass.length < 4) return { ok: false, error: "Password baru minimal 4 karakter." };
    if (!verifyCodeForUser(user, code)) {
      return { ok: false, error: "Kode verifikasi salah atau kedaluwarsa (maks. 10 menit). Minta kode baru dari langkah pertama." };
    }
    setStoredPassword(user, pass);
    clearResetSession();
    return { ok: true };
  }, []);

  const value = useMemo(
    () => ({
      username,
      login,
      logout,
      sendPasswordResetCode,
      completePasswordReset,
    }),
    [username, login, logout, sendPasswordResetCode, completePasswordReset],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth outside AuthProvider");
  return ctx;
}

import { useState } from "react";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useToast } from "../context/ToastContext";

type Step = "request" | "verify";

export default function ForgotPassword() {
  const { username, sendPasswordResetCode, completePasswordReset } = useAuth();
  const { push } = useToast();
  const nav = useNavigate();

  const [step, setStep] = useState<Step>("request");
  const [u, setU] = useState("");
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);

  const [code, setCode] = useState("");
  const [p1, setP1] = useState("");
  const [p2, setP2] = useState("");
  const [demoCode, setDemoCode] = useState<string | null>(null);

  if (username) return <Navigate to="/dashboard" replace />;

  async function onRequest(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setDemoCode(null);
    const res = await sendPasswordResetCode(u, email);
    setLoading(false);
    if (!res.ok) {
      push(res.error, "error");
      return;
    }
    setDemoCode(res.code);
    setStep("verify");
    push("Kode autentifikasi siap. Periksa petunjuk di layar (mode tanpa server).", "success");
  }

  function onReset(e: React.FormEvent) {
    e.preventDefault();
    if (p1 !== p2) {
      push("Konfirmasi password tidak sama.", "error");
      return;
    }
    const res = completePasswordReset(u, code, p1);
    if (!res.ok) {
      push(res.error, "error");
      return;
    }
    push("Password berhasil diubah. Silakan masuk.", "success");
    nav("/login", { replace: true });
  }

  return (
    <div
      style={{
        minHeight: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: "1.5rem",
        background: "var(--color-cream)",
      }}
    >
      <div className="card" style={{ width: "100%", maxWidth: 420, padding: "1.75rem" }}>
        <h1 style={{ margin: "0 0 0.25rem", fontSize: "1.4rem", color: "var(--color-primary-dark)" }}>Lupa password</h1>
        <p style={{ margin: "0 0 1.25rem", color: "var(--color-muted)", fontSize: "0.88rem", lineHeight: 1.5 }}>
          {step === "request"
            ? "Masukkan username dan email. Pada aplikasi nyata, kode dikirim ke email Anda. Di sini tanpa server, kode ditampilkan setelah langkah berikut."
            : "Masukkan kode 6 digit dan password baru Anda."}
        </p>

        {step === "request" ? (
          <form onSubmit={onRequest}>
            <div style={{ marginBottom: "1rem" }}>
              <label className="label" htmlFor="fu">
                Username
              </label>
              <input
                id="fu"
                className="input"
                autoComplete="username"
                value={u}
                onChange={(e) => setU(e.target.value)}
                placeholder="admin"
                required
              />
            </div>
            <div style={{ marginBottom: "1rem" }}>
              <label className="label" htmlFor="em">
                Email terdaftar
              </label>
              <input
                id="em"
