/**
 * Password utama + nama pengguna (lokal, tanpa server).
 * Bukan untuk lingkungan produksi yang membutuhkan keamanan tinggi.
 */

const MASTER_KEY = "pempek_novi_master_auth_v1";
const LEGACY_CRED_KEY = "pempek_novi_credentials_v1";
const LEGACY_AUTH_KEY = "pempek_novi_auth_v1";

export type MasterAuthFile = {
  masterPassword: string;
  displayName: string;
};

const DEFAULT_MASTER = "admin";
const DEFAULT_DISPLAY = "Admin";

function defaultFile(): MasterAuthFile {
  return { masterPassword: DEFAULT_MASTER, displayName: DEFAULT_DISPLAY };
}

function migrateFromLegacy(): MasterAuthFile | null {
  try {
    const raw = localStorage.getItem(LEGACY_CRED_KEY);
    if (!raw) return null;
    const j = JSON.parse(raw) as { passwords?: Record<string, string> };
    const adminPass = j?.passwords?.admin;
    if (typeof adminPass === "string" && adminPass.length > 0) {
      let displayName = DEFAULT_DISPLAY;
      try {
        const a = JSON.parse(localStorage.getItem(LEGACY_AUTH_KEY) || "{}") as { username?: string };
        if (typeof a.username === "string" && a.username.trim()) displayName = a.username.trim();
      } catch {
        /* ignore */
      }
      return { masterPassword: adminPass, displayName };
    }
  } catch {
    /* ignore */
  }
  return null;
}

export function loadMasterAuth(): MasterAuthFile {
  try {
    const raw = localStorage.getItem(MASTER_KEY);
    if (raw) {
      const j = JSON.parse(raw) as MasterAuthFile;
      if (typeof j.masterPassword === "string" && j.masterPassword.length > 0) {
        return {
          masterPassword: j.masterPassword,
          displayName: typeof j.displayName === "string" && j.displayName.trim() ? j.displayName.trim() : DEFAULT_DISPLAY,
        };
      }
    }
  } catch {
    /* ignore */
  }
  const migrated = migrateFromLegacy();
  if (migrated) {
    saveMasterAuth(migrated);
    return migrated;
  }
  return defaultFile();
}

export function saveMasterAuth(f: MasterAuthFile) {
  localStorage.setItem(
    MASTER_KEY,
    JSON.stringify({
      masterPassword: f.masterPassword,
      displayName: f.displayName.trim() || DEFAULT_DISPLAY,
    }),
  );
}

export function verifyMasterPassword(candidate: string): boolean {
  const f = loadMasterAuth();
  return f.masterPassword === candidate;
}

export function setMasterPassword(newPassword: string) {
  const f = loadMasterAuth();
  f.masterPassword = newPassword;
  saveMasterAuth(f);
}

export function getDisplayName(): string {
  return loadMasterAuth().displayName;
}

export function setDisplayName(name: string) {
  const f = loadMasterAuth();
  f.displayName = name.trim() || DEFAULT_DISPLAY;
  saveMasterAuth(f);
}

/** Hapus password & nama tersimpan + file legacy (kembali ke bawaan). */
export function clearAllCredentials() {
  localStorage.removeItem(MASTER_KEY);
  localStorage.removeItem(LEGACY_CRED_KEY);
}

const SESSION_KEY = "pempek_novi_session_v1";

export function isSessionActive(): boolean {
  try {
    return localStorage.getItem(SESSION_KEY) === "1";
  } catch {
    return false;
  }
}

export function setSessionActive(active: boolean) {
  if (active) localStorage.setItem(SESSION_KEY, "1");
  else localStorage.removeItem(SESSION_KEY);
}

export function clearSession() {
  localStorage.removeItem(SESSION_KEY);
}

