import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  getDisplayName,
  loadMasterAuth,
  setDisplayName as persistDisplayName,
  setMasterPassword,
  verifyMasterPassword,
} from "../auth/localCredentials";
import { clearSession, isSessionActive, setSessionActive } from "../auth/session";

type AuthContextValue = {
  /** Sudah memasukkan password utama di sesi ini */
  isLoggedIn: boolean;
  /** Nama pengguna tampilan (bukan untuk login) */
  displayName: string;
  login: (password: string) => boolean;
  logout: () => void;
  updateDisplayName: (name: string) => void;
  changeMasterPassword: (currentPassword: string, newPassword: string) => { ok: true } | { ok: false; error: string };
  refreshDisplayName: () => void;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [isLoggedIn, setIsLoggedIn] = useState(() => isSessionActive());
  const [displayName, setDisplayNameState] = useState(() => getDisplayName());

  const refreshDisplayName = useCallback(() => {
    setDisplayNameState(getDisplayName());
  }, []);

  const login = useCallback((password: string) => {
    const p = password.trim();
    if (!p) return false;
    if (!verifyMasterPassword(p)) return false;
    setSessionActive(true);
    setIsLoggedIn(true);
    setDisplayNameState(getDisplayName());
    return true;
  }, []);

  const logout = useCallback(() => {
    clearSession();
    setIsLoggedIn(false);
  }, []);

  const updateDisplayName = useCallback((name: string) => {
    persistDisplayName(name);
    setDisplayNameState(getDisplayName());
  }, []);

  const changeMasterPassword = useCallback((currentPassword: string, newPassword: string) => {
    const cur = currentPassword.trim();
    const next = newPassword.trim();
    if (!verifyMasterPassword(cur)) return { ok: false, error: "Password saat ini salah." };
    if (next.length < 4) return { ok: false, error: "Password baru minimal 4 karakter." };
    setMasterPassword(next);
    loadMasterAuth();
    return { ok: true };
  }, []);

  const value = useMemo(
    () => ({
      isLoggedIn,
      displayName,
      login,
      logout,
      updateDisplayName,
      changeMasterPassword,
      refreshDisplayName,
    }),
    [isLoggedIn, displayName, login, logout, updateDisplayName, changeMasterPassword, refreshDisplayName],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth outside AuthProvider");
  return ctx;
}

